const { createContext, useContext, useReducer } = React;
const CartContext = createContext(null);
function cartReducer(state, action) {
  if (action.type === 'add') return { count: state.count + 1 };
  if (action.type === 'clear') return { count: 0 };
  return state;
}
function CartProvider({ children }) {
  const [state, dispatch] = useReducer(cartReducer, { count: 0 });
  return <CartContext.Provider value={{ state, dispatch }}>{children}</CartContext.Provider>;
}
function CartSummary() { const { state } = useContext(CartContext); return <p>장바구니: {state.count}개</p>; }
function CartButtons() { const { dispatch } = useContext(CartContext); return <><button onClick={() => dispatch({ type: 'add' })}>추가</button><button onClick={() => dispatch({ type: 'clear' })}>비우기</button></>; }
function App() { return <CartProvider><CartSummary /><CartButtons /></CartProvider>; }
ReactDOM.createRoot(document.querySelector('#root')).render(<App />);
